  Future<void> _uploadEditImageToImgur() async {
    if (_editImageFile == null) return;
    setState(() => _isUploadingEditImage = true);
    _editUploadedImageUrl = null;
    try {
      _editUploadedImageUrl =
          await TransporterApiService.uploadImageToImgur(_editImageFile!);
      if (!mounted) return;
      setState(() => _isUploadingEditImage = false);
      if (_editUploadedImageUrl != null) {
        _showSnackBar("New image uploaded. Save profile to apply.",
            isError: false);
      } else {
        _showErrorSnackbar("Image upload failed.");
      }
    } catch (e) {
      print("Error in _uploadEditImageToImgur UI: $e");
      if (!mounted) return;
      setState(() => _isUploadingEditImage = false);
      _showErrorSnackbar("Image upload failed: $e");
    }
  }

  // --- Edit Mode Toggles ---
  void _enterEditMode() {
    if (_currentProfile == null || !mounted) return;
    setState(() {
      _isEditing = true;
      _nameController.text = _currentProfile!.name;
      _phoneController.text = _currentProfile!.phoneNumber ?? '';
      _vehicleTypeController.text = _currentProfile!.vehicleType ?? '';
      _licensePlateController.text = _currentProfile!.licensePlate ?? '';
      _locationController.text = _currentProfile!.location ?? '';
      _editImageFile = null;
      _editUploadedImageUrl = null;
    });
  }

  void _cancelEditMode() {
    if (!mounted) return;
    setState(() {
      _isEditing = false;
      _editImageFile = null;
      _editUploadedImageUrl = null;
      _profileFormKey.currentState?.reset();
    });
  }

  // --- Save Profile Changes ---
  Future<void> _saveChanges() async {
    if (_currentProfile == null || !_isEditing || !mounted) return;
    FocusScope.of(context).unfocus();

    if (_profileFormKey.currentState?.validate() ?? false) {
      if (_isUploadingEditImage) {
        _showErrorSnackbar('Image is still uploading. Please wait.');
        return;
      }
      setState(() => _isLoadingStatus = true);
      _showLoadingSnackbar("Saving profile...");

      // --- Build updateData only with changed fields ---
      Map<String, dynamic> updateData = {};
      final originalProfile =
          _currentProfile!; // Already checked for null earlier

      final newName = _nameController.text.trim();
      if (newName != originalProfile.name) {
        updateData['name'] = newName;
      }

      final newPhone = _phoneController.text.trim();
      if (newPhone != (originalProfile.phoneNumber ?? '')) {
        updateData['phone_number'] = newPhone;
      }

      final newVehicle = _vehicleTypeController.text.trim();
      if (newVehicle != (originalProfile.vehicleType ?? '')) {
        updateData['vehicle_type'] = newVehicle;
      }

      final newPlate = _licensePlateController.text.trim();
      if (newPlate != (originalProfile.licensePlate ?? '')) {
        updateData['license_plate'] = newPlate;
      }

      final newLocation = _locationController.text.trim();
      if (newLocation != (originalProfile.location ?? '')) {
        updateData['location'] = newLocation;
      }

      if (_editUploadedImageUrl != null &&
          _editUploadedImageUrl != originalProfile.profileImageUrl) {
        updateData['profile_image_url'] = _editUploadedImageUrl;
      }
      // --- End building updateData ---

      // Check if there are any actual changes
      if (updateData.isEmpty) {
        _dismissLoadingSnackbar();
        if (mounted) {
          setState(() => _isLoadingStatus = false);
          _showSnackBar("No changes detected.", isError: false);
          _cancelEditMode(); // Exit edit mode as nothing changed
        }
        return;
      }

      try {
        bool success =
            // Pass ID to update profile
            // Access ID via widget.transporterId
            await TransporterApiService.updateTransporterProfile(
                widget.transporterId, updateData);
        _dismissLoadingSnackbar();
        if (!mounted) return;
        setState(() => _isLoadingStatus = false);
        if (success) {
          _showSuccessSnackbar('Profile updated successfully!');
          _refreshProfile(); // Reload to see changes
        } else {
          _showErrorSnackbar('Failed to save profile changes.');
        }
      } catch (e) {
        print("Error saving profile changes via API: $e");
        _dismissLoadingSnackbar();
        if (mounted) {
          setState(() => _isLoadingStatus = false);
          _showErrorSnackbar('An error occurred: $e');
        }
      }
    } else {
      _showSnackBar('Please fix form errors.', isError: true);
    }
  }

  // --- Toggle Active Status ---
  Future<void> _toggleActiveStatus(bool newValue) async {
    if (_currentProfile == null || !mounted || _isEditing) return;
    setState(() => _isLoadingStatus = true);
    _showLoadingSnackbar(newValue ? "Going Online..." : "Going Offline...");

    try {
      bool success =
          // Pass ID to update status
          // Access ID via widget.transporterId
          await TransporterApiService.updateTransporterStatus(
              widget.transporterId, newValue);
      _dismissLoadingSnackbar();
      if (!mounted) return;
      setState(() => _isLoadingStatus = false);
      if (success) {
        setState(() {
          _currentProfile = _currentProfile!.copyWith(isActive: newValue);
        });
        _showSuccessSnackbar(
            newValue ? 'You are now Online!' : 'You are now Offline.');
      } else {
        _showErrorSnackbar('Failed to update status.');
      }
    } catch (e) {
      print("Error toggling active status: $e");
      _dismissLoadingSnackbar();
      if (mounted) {
        setState(() => _isLoadingStatus = false);
        _showErrorSnackbar('An error occurred: $e');
      }
    }
  }

  // --- Snackbar Helpers ---
  void _showSnackBar(String message,
      {bool isError = false, int durationSeconds = 3}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).removeCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message,
            style: TextStyle(color: isError ? whiteColor : textOnTeal),
            textAlign: TextAlign.center),
        backgroundColor: isError
            ? errorColor.withOpacity(0.9)
            : primaryTeal.withOpacity(0.9),
        duration: Duration(seconds: durationSeconds),
        behavior: SnackBarBehavior.floating,
        margin: const EdgeInsets.symmetric(vertical: 20.0, horizontal: 15.0),
        padding: const EdgeInsets.symmetric(vertical: 12.0, horizontal: 15.0),
        shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(10.0)),
        elevation: 4.0,
      ),
    );
  }

  void _showErrorSnackbar(String message) {
    _showSnackBar(message, isError: true, durationSeconds: 4);
  }

  void _showSuccessSnackbar(String message) {
    _showSnackBar(message, isError: false);
  }

  void _showLoadingSnackbar(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).removeCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const SizedBox(
              width: 16,
              height: 16,
              child: CircularProgressIndicator(
                  strokeWidth: 2, color: Colors.white)),
          const SizedBox(width: 12),
          Text(message, style: const TextStyle(color: Colors.white))
        ],
      ),
      backgroundColor: Colors.black.withOpacity(0.7),
      duration: const Duration(seconds: 60),
      behavior: SnackBarBehavior.floating,
      margin: const EdgeInsets.symmetric(vertical: 20.0, horizontal: 50.0),
      padding: const EdgeInsets.symmetric(vertical: 10.0, horizontal: 15.0),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20.0)),
    ));
  }

  void _dismissLoadingSnackbar() {
    if (mounted) ScaffoldMessenger.of(context).removeCurrentSnackBar();
  }

  @override
  Widget build(BuildContext context) {
    // Use _isLoadingProfile and _profileFetchError for state management
    if (_isLoadingProfile && _currentProfile == null) {
      return _buildProfileShimmer();
    }
    if (_profileFetchError.isNotEmpty && _currentProfile == null) {
      // Show error state only if there's no cached data to display
      return _buildErrorState(_profileFetchError);
    }
    // If _currentProfile is null here, it means there was no cache and fetch failed
    if (_currentProfile == null) {
      // This case should ideally be caught by the error state above, but as a safeguard:
      return _buildEmptyState(
          "Profile Not Found", "Could not load your profile details.");
    }

    final profile =
        _currentProfile!; // Use the potentially cached or fresh profile
    return RefreshIndicator(
      onRefresh: _refreshProfile, // Use the new refresh method
      color: primaryTeal,
      child: Form(
        key: _profileFormKey,
        child: ListView(
          padding: const EdgeInsets.all(16.0),
          physics: const AlwaysScrollableScrollPhysics(),
          children: [
            _buildProfileHeaderSection(profile),
            const SizedBox(height: 20),
            _buildVehicleInfoSection(profile),
            const SizedBox(height: 20),
            _buildAccountStatusSection(profile),
            const SizedBox(height: 80),
            // Show loading indicator if a background fetch is in progress AND we are not editing
            if (_isLoadingProfile && !_isEditing)
              const LinearProgressIndicator(),
          ],
        ),
      ),
    );
  }

