  void _updateStateWithPreferences(Map<String, dynamic> prefData) {
    if (!mounted) return;
    
    setState(() {
      _userPreferences = {
        'goals': getCaseInsensitive(prefData, 'goals') ?? 'N/A',
        'diet_type': getCaseInsensitive(prefData, 'diet_type') ?? 'N/A',
        'food_restrictions': _listToString(getCaseInsensitive(prefData, 'food_restrictions'), emptyValue: 'None'),
        'cuisine_preferences': getCaseInsensitive(prefData, 'cuisine_preferences') ?? 'Any',
      };
      
      _isLoadingPreferences = false;
      
      if (!_isEditingPreferences) {
        _selectedGoal = _userPreferences['goals'] != 'N/A' ? _userPreferences['goals'] : null;
        if (_selectedGoal != null && !_goalsOptions.contains(_selectedGoal)) {
          _selectedGoal = null;
        }

        _selectedDietType = _userPreferences['diet_type'] != 'N/A' ? _userPreferences['diet_type'] : null;
        if (_selectedDietType != null && !_dietTypeOptions.contains(_selectedDietType)) {
          _selectedDietType = null;
        }

        String? currentRestrictionDisplay = _userPreferences['food_restrictions'];
        if (currentRestrictionDisplay == 'None') {
          _selectedFoodRestriction = 'None';
        } else if (currentRestrictionDisplay != null && currentRestrictionDisplay != 'N/A') {
          String firstItem = currentRestrictionDisplay.split(',').first.trim();
          _selectedFoodRestriction = _foodRestrictionsOptions.contains(firstItem) ? firstItem : null;
        } else {
          _selectedFoodRestriction = null;
        }
        
        if (_selectedFoodRestriction != null && !_foodRestrictionsOptions.contains(_selectedFoodRestriction)) {
          _selectedFoodRestriction = null;
        }

        // Update single cuisine preference
        _selectedCuisine = _userPreferences['cuisine_preferences'];
        if (_selectedCuisine != null && !_cuisinePreferencesOptions.contains(_selectedCuisine)) {
          _selectedCuisine = null; // Reset if the value from API is not in our options
        }
      }
    });
  }

  String _listToString(dynamic listOrString, {String emptyValue = 'N/A'}) {
    if (listOrString == null) return emptyValue;
    if (listOrString is List) {
      if (listOrString.isEmpty) return emptyValue;
      return listOrString.join(', ');
    }
    if (listOrString is String) {
      return listOrString.isEmpty ? emptyValue : listOrString;
    }
    return listOrString.toString();
  }

  String? _getFirstItemFromListOrString(dynamic data) {
    if (data == null) return null;
    if (data is List && data.isNotEmpty) {
      return data.first.toString();
    }
    if (data is String && data.isNotEmpty) {
      return data.split(',').first.trim();
    }
    return null;
  }

  Future<void> _pickImage() async {
    try {
      final XFile? image = await _picker.pickImage(source: ImageSource.gallery);
      if (image != null) {
        final File imageFile = File(image.path);
        await _uploadImage(imageFile);
      }
    } catch (e) {
      debugPrint("Error picking image: $e");
      if (mounted) _showErrorSnackBar('Error picking image: $e');
    }
  }

  Future<void> _uploadImage(File imageFile) async {
    if (_userId == null) {
      _showErrorSnackBar('User ID not found. Cannot upload image.');
      return;
    }
    _showSuccessSnackBar('Processing image...');

    try {
      // 1. Upload to Imgur
      final imgurUrl = await _uploadToImgur(imageFile);
      if (imgurUrl == null) {
        _showErrorSnackBar('Failed to upload image to Imgur');
        return;
      }

      // 2. Update user profile with the new image URL
      final response = await http.patch(
        Uri.parse('$apiBaseUrl/rr/users/$_userId'),
        headers: {'Content-Type': 'application/json'},
        body: json.encode({'image': imgurUrl}),
      );

      if (response.statusCode == 200) {
        // Update local state
        setState(() {
          _profileImageUrl = imgurUrl;
          _profileImagePath = null; // Clear local path if server URL is used
          _userDetails['image'] = imgurUrl;
        });
        
        // Update cache
        await UserCache.saveData('user_details_cache', _userDetails);
        await _saveImageToPrefs(''); // Clear local path pref
        _showSuccessSnackBar('Profile image updated successfully!');
      } else {
        final error = jsonDecode(response.body)?['message'] ?? 'Unknown error';
        _showErrorSnackBar('Failed to update profile: $error');
      }
    } on TimeoutException {
      _showErrorSnackBar('Image upload timed out. Please try again.');
    } on http.ClientException catch (e) {
      debugPrint('Network error during image upload: $e');
      _showErrorSnackBar('Network error. Please check your connection.');
    } catch (e) {
      debugPrint('Error uploading image: $e');
      _showErrorSnackBar('Failed to upload image. Please try again.');
    }
  }

  Future<String?> _uploadToImgur(File imageFile) async {
    try {
      final request = http.MultipartRequest(
        'POST',
        Uri.parse('https://api.imgur.com/3/image'),
      );
      
      // Set authorization header with Client-ID
      request.headers['Authorization'] = 'Client-ID $imgurClientID';
      
      // Add image file to the request
      request.files.add(
        await http.MultipartFile.fromPath('image', imageFile.path),
      );

      // Send the request
      final streamedResponse = await request.send();
      final response = await http.Response.fromStream(streamedResponse);
      final responseData = jsonDecode(response.body);
      
      debugPrint('Imgur upload response: ${response.statusCode} ${response.body}');
      
      if (response.statusCode == 200 && 
          responseData['success'] == true && 
          responseData['data']?['link'] != null) {
        return responseData['data']['link'].toString();
      } else {
        final error = responseData['data']?['error'] ?? 'Unknown Imgur error';
        debugPrint('Imgur upload failed: $error');
        return null;
      }
    } catch (e) {
      debugPrint('Error in _uploadToImgur: $e');
      return null;
    }
  }

