      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SizedBox(
            width: 100,
            child: Text(label,
              style: GoogleFonts.poppins(
                color: kColorTextSecondary,
              ),
            ),
          ),
          Expanded(
            child: Text(value,
              style: GoogleFonts.poppins(
                fontWeight: FontWeight.w500,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildTrackingEvent(String event, String date, {bool isLast = false}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Column(
            children: [
              Container(
                width: 12,
                height: 12,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: kColorStatusActive,
                ),
              ),
              if (!isLast)
                Container(
                  width: 2,
                  height: 40,
                  color: kColorStatusActive,
                ),
            ],
          ),
          const SizedBox(width: 16),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(event,
                  style: GoogleFonts.poppins(
                    fontWeight: FontWeight.w500,
                  ),
                ),
                Text(date,
                  style: GoogleFonts.poppins(
                    color: kColorTextSecondary,
                    fontSize: 12,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildLoadingState() {
    return Center(
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          CircularProgressIndicator(color: kColorPrimary),
          const SizedBox(height: 16),
          Text('Loading order details...',
            style: GoogleFonts.poppins(
              color: kColorTextPrimary,
            ),
          ),
        ],
      ),
    );
  }

  // Helper methods
  String _formatDate(String? dateString) {
    if (dateString == null) return 'N/A';
    try {
      final dateTime = DateTime.parse(dateString);
      return DateFormat('d MMM y').format(dateTime);
    } catch (e) {
      return dateString;
    }
  }

  String _estimateDispatchDate(String? orderDate) {
    if (orderDate == null) return 'N/A';
    try {
      final dateTime = DateTime.parse(orderDate).add(const Duration(days: 1));
      return DateFormat('d MMM').format(dateTime);
    } catch (e) {
      return 'N/A';
    }
  }

  String _formatStatus(String status) {
    return status.replaceAll('_', ' ').split(' ').map((word) => 
      word.isNotEmpty ? word[0].toUpperCase() + word.substring(1).toLowerCase() : ''
    ).join(' ').trim();
  }

  List<String> _generateStatusDates(String? orderDate) {
    if (orderDate == null) return ['N/A', 'N/A', 'N/A'];
    try {
      final dateTime = DateTime.parse(orderDate);
      return [
        DateFormat('d MMM').format(dateTime),
        DateFormat('d MMM').format(dateTime.add(const Duration(days: 1))),
        DateFormat('d MMM').format(dateTime.add(const Duration(days: 2))),
      ];
    } catch (e) {
      return ['N/A', 'N/A', 'N/A'];
    }
  }

  int _getStatusIndex(String status) {
    switch (status.toLowerCase()) {
      case 'placed':
      case 'order_placed':
        return 0;
      case 'dispatched':
      case 'shipped':
        return 1;
      case 'delivered':
      case 'completed':
        return 2;
      default:
        return 0;
    }
  }
