  Future<String> _uploadImageToImgur(File image) async {
    if (imgurClientID.isEmpty)
      throw Exception('Imgur Client ID is not configured.');

    var request = http.MultipartRequest(
        'POST', Uri.parse('https://api.imgur.com/3/image'));
    request.headers['Authorization'] = 'Client-ID $imgurClientID';
    request.files.add(await http.MultipartFile.fromPath('image', image.path));

    final streamedResponse =
        await request.send().timeout(const Duration(seconds: 30));
    final response = await http.Response.fromStream(streamedResponse);

    if (response.statusCode == 200) {
      final jsonResponse = json.decode(response.body);
      if (jsonResponse['success'] == true &&
          jsonResponse['data']?['link'] != null) {
        return jsonResponse['data']['link'];
      } else {
        throw Exception('Imgur upload failed: Invalid response structure.');
      }
    } else {
      print("Imgur Upload Error: ${response.body}");
      throw Exception(
          'Failed to upload image. Status Code: ${response.statusCode}');
    }
  }

  // --- Location Handling (Adapted from ChefSignUpPage) ---

  void _startLocationHintAnimation() {
    _locationHintTimer?.cancel();
    _locationHintDots = 0;
    _locationHintTimer =
        Timer.periodic(const Duration(milliseconds: 400), (timer) {
      if (!mounted || !_isFetchingLocation) {
        timer.cancel();
        if (mounted && !_isFetchingLocation)
          setState(() => _locationHintDots = 0);
        return;
      }
      setState(() => _locationHintDots = (_locationHintDots + 1) % 4);
    });
  }

  void _stopLocationHintAnimation() {
    _locationHintTimer?.cancel();
    if (mounted) setState(() => _locationHintDots = 0);
  }

  // --- CORRECTED _getCurrentLocation ---
  Future<void> _getCurrentLocation() async {
    if (_isFetchingLocation) return;

    setState(() {
      _isFetchingLocation = true; // Use specific flag
      locationController.clear(); // Clear the data controller
    });
    _startLocationHintAnimation();

    try {
      bool serviceEnabled = await Geolocator.isLocationServiceEnabled();
      if (!serviceEnabled) throw Exception('Location services are disabled.');

      LocationPermission permission = await Geolocator.checkPermission();
      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
        if (permission == LocationPermission.denied)
          throw Exception('Location permissions denied.');
      }
      if (permission == LocationPermission.deniedForever)
        throw Exception('Location permissions permanently denied.');

      Position position = await Geolocator.getCurrentPosition(
          desiredAccuracy: LocationAccuracy.high,
          timeLimit: const Duration(seconds: 15));

      // Reverse Geocoding
      String displayAddress =
          "Lat: ${position.latitude.toStringAsFixed(4)}, Lon: ${position.longitude.toStringAsFixed(4)}";
      String coords =
          "${position.latitude}, ${position.longitude}"; // Store coordinates separately

      try {
        final String apiUrl =
            'https://geocode.maps.co/reverse?lat=${position.latitude}&lon=${position.longitude}';
        final response = await http
            .get(Uri.parse(apiUrl))
            .timeout(const Duration(seconds: 10));
        if (response.statusCode == 200) {
          final data = json.decode(response.body);
          // Use the fetched address if available and valid
          displayAddress = data['display_name'] ?? displayAddress;
        } else {
          print("Reverse geocode error: ${response.statusCode}");
          // Keep displayAddress as coordinates, show snackbar
          _showSnackBar('Could not fetch readable address.', isError: true);
        }
      } catch (e) {
        // Keep displayAddress as coordinates, show snackbar
        print("Reverse geocode exception: $e");
        // ERROR LINE REMOVED FROM HERE
        _showSnackBar('Could not fetch readable address.', isError: true);
      }

      _stopLocationHintAnimation();
      setState(() {
        // Update the text controller with the best available address string
        // Add coordinates in parentheses for clarity/storage if needed
        locationController.text = (displayAddress.isNotEmpty &&
                !displayAddress.startsWith("Lat:"))
            ? "$displayAddress ($coords)"
            : coords; // Just send coordinates if reverse geocoding fails
        _isFetchingLocation = false;
      });
      _showSnackBar('Location acquired successfully!', isError: false);
    } on TimeoutException catch (_) {
      _stopLocationHintAnimation();
      setState(() {
        _isFetchingLocation = false;
        locationController.text =
            'Failed to get location (Timeout)'; // Indicate failure in field
      });
      _showSnackBar('Getting location timed out.', isError: true);
    } catch (e) {
      _stopLocationHintAnimation();
      setState(() {
        _isFetchingLocation = false;
        locationController.text =
            'Failed to get location'; // Indicate failure in field
      });
      _showSnackBar('Error getting location: $e', isError: true);
    }
  }
  // --- End CORRECTED _getCurrentLocation ---

  // --- Form Submission (Keep existing logic) ---
  Future<void> submitData() async {
    // --- Validation Checks ---
    if (!_formKey.currentState!.validate()) {
      _showSnackBar('Please fix the errors in the form.',
          isError: true, isWarning: true);
      return;
    }
    if (passwordController.text != confirmPasswordController.text) {
      _showSnackBar('Passwords do not match.', isError: true, isWarning: true);
      return;
    }
    
    // Make profile image optional
    bool continueWithoutImage = false;
    if (imageUrlController.text.isEmpty) {
      final shouldContinue = await showDialog<bool>(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('No Profile Image'),
          content: const Text('You can continue without a profile image and add one later from your profile settings. Would you like to continue?'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('Go Back'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(context, true),
              child: const Text('Continue'),
            ),
          ],
        ),
      ) ?? false;
      
      if (!shouldContinue) {
        return;
      }
      continueWithoutImage = true;
    }
    
    // Make location optional
    if (locationController.text.isEmpty ||
        locationController.text.startsWith('Failed to get location')) {
      final shouldContinue = await showDialog<bool>(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('Location Not Set'),
          content: const Text('You can continue without setting a location and update it later from your profile settings. Would you like to continue?'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('Go Back'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(context, true),
              child: const Text('Continue'),
            ),
          ],
        ),
      ) ?? false;
      
      if (!shouldContinue) {
        return;
      }
    }
    if (_sampleImageUrls
        .where((url) => url != null && url.isNotEmpty)
        .isEmpty) {
      _showSnackBar('Please upload at least one sample menu image.',
          isError: true, isWarning: true);
      return;
    }
    if (selectedChefType == 'Individual') {
      final key50plus = perGigCategoryKeys['50+ people']!;
      final key100plus = perGigCategoryKeys['100+ people']!;
      if (perGigPriceControllers[key50plus]!.text.isNotEmpty ||
          perGigPriceControllers[key100plus]!.text.isNotEmpty) {
        print("Clearing large group pricing for Individual chef.");
        perGigPriceControllers[key50plus]?.clear();
        perGigPriceControllers[key100plus]?.clear();
      }
    }
    // --- End Validation ---

    setState(() => _isLoading = true); // General submit loading

    // --- Prepare Pricing Data ---
    Map<String, dynamic> perGigPrices = {};
    perGigPriceControllers.forEach((key, controller) {
      double? price = double.tryParse(controller.text.trim());
      bool isLargeGroupKey = key == perGigCategoryKeys['50+ people']! ||
          key == perGigCategoryKeys['100+ people']!;
      if (price != null &&
          (selectedChefType == 'Company' || !isLargeGroupKey)) {
        perGigPrices[key] = price;
      }
    });
    double? monthlyPrice = double.tryParse(monthlyPriceController.text.trim());
    double? startingPrice =
        double.tryParse(startingPriceController.text.trim());
    Map<String, dynamic> pricingData = {
      'starting_price': startingPrice ?? 0.0,
      'per_gig': perGigPrices,
      'per_month': monthlyPrice
    };

    // --- Prepare List Data ---
    List<String> finalSampleMenuUrls = _sampleImageUrls
        .where((url) => url != null && url.isNotEmpty)
        .cast<String>()
        .toList();
    String equipmentJson =
        json.encode(equipment.isEmpty ? ['None'] : equipment);
    String availabilityJson =
        json.encode(availability.isEmpty ? [] : availability);
    String languagesJson = json.encode(languages.isEmpty ? [] : languages);
    String specialtiesJson =
        json.encode(specialties.isEmpty ? [] : specialties);
    String certificationsJson =
        json.encode(certifications.isEmpty ? ['None'] : certifications);
    String sampleMenuJson = json.encode(finalSampleMenuUrls);

    // --- Prepare Full Payload ---
    final chefData = {
      'name': nameController.text.trim(),
      'email': emailController.text.trim(),
      'password': passwordController.text.trim(),
      'image': continueWithoutImage ? '' : imageUrlController.text.trim(),
      'phone_number': phoneNumberController.text.trim(),
      'location': (locationController.text.isEmpty || 
                  locationController.text.startsWith('Failed to get location')) 
                  ? '' 
                  : locationController.text.trim(),
      'chef_type': selectedChefType,
      'experience': int.tryParse(experienceController.text.trim()) ?? 0,
      'responsetime': selectedResponseTime,
      'minnotice': selectedMinNotice,
      'teamsize': selectedTeamSize,
      'bio': bioController.text.trim(),
      'is_active': true,
      'rating': 0.0,
      'registration_date': DateTime.now().toIso8601String(),
      'last_login': DateTime.now().toIso8601String(),
      'pricing': pricingData,
      'equipment': equipmentJson,
      'availability': availabilityJson,
      'languages': languagesJson,
      'specialties': specialtiesJson,
      'certifications': certificationsJson,
      'samplemenu': sampleMenuJson,
    };

    // --- API Call ---
    final String apiUrl = '$apibaseurl/rr/signup_chef';
    try {
      print("Sending data to $apiUrl...");
      final response = await http.post(Uri.parse(apiUrl),
          headers: {"Content-Type": "application/json"},
          body: json.encode(chefData));

      print("API Response Status: ${response.statusCode}");

      if (response.statusCode == 201) {
        final responseData = json.decode(response.body);
        final int? chefID = responseData['ChefID'];
        final String? userType = responseData['UserType'];
        final String? phoneNumber = responseData['phone'] as String?;

        if (chefID != null && userType != null) {
          final prefs = await SharedPreferences.getInstance();
          await prefs.setString('chef_user_id', chefID.toString());
          await prefs.setString('user_id', chefID.toString());
          await prefs.setString('user_type', userType);
          await prefs.setString('chef_user_type', userType);
          await prefs.setBool('is_logged_in', true);
          
          // Save phone number if available in the response
          if (phoneNumber != null && phoneNumber.isNotEmpty) {
            await prefs.setString('user_phone', phoneNumber);
          }
          
          // NotificationService automatically handles token registration during initialization
          print('Saved ChefID: $chefID, UserType: $userType, Phone: $phoneNumber');
        }

        _showSnackBar('Chef registration successful!', isError: false);
        Navigator.pushReplacement(
            context,
            MaterialPageRoute(
                builder: (context) =>
                    EmailVerificationPage())); // Navigate to verification page
      } else {
        String errorMessage = 'Failed to submit data.';
        try {
          if (response.statusCode == 409) {
            errorMessage = 'An account with this email already exists. Please log in or use a different email.';
          } else {
            final errorData = json.decode(response.body);
            errorMessage +=
                ' Error: ${errorData['message'] ?? response.reasonPhrase}';
          }
        } catch (_) {
          if (response.statusCode == 409) {
            errorMessage = 'An account with this email already exists. Please log in or use a different email.';
          } else {
            errorMessage += ' Status code: ${response.statusCode}';
          }
        }
        _showSnackBar(errorMessage, isError: true);
      }
    } catch (error) {
      print("Submission Error: $error");
      _showSnackBar('An error occurred: $error', isError: true);
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  // --- SnackBar Helper (Adapted) ---
  void _showSnackBar(String message,
      {bool isError = false, bool isWarning = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).removeCurrentSnackBar();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message, style: const TextStyle(color: whiteColor)),
        backgroundColor: isError
            ? errorColor
            : (isWarning ? Colors.orange[700] : accentTeal),
        behavior: SnackBarBehavior.floating,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(8)),
        margin: const EdgeInsets.all(15),
        duration: Duration(seconds: isError ? 4 : 3),
      ),
    );
  }

