  Future<void> _signOut() async {
    final bool? confirm = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text('Confirm Sign Out'),
        content: Text('Are you sure you want to sign out?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: Text('Cancel', style: TextStyle(color: _grey))),
          TextButton(
              onPressed: () => Navigator.pop(context, true),
              child: Text('Sign Out', style: TextStyle(color: _red))),
        ],
      ),
    );
    if (confirm == true) {
      try {
        SharedPreferences prefs = await SharedPreferences.getInstance();
        await prefs.remove('transporter_token'); // Adjust key if needed
        await prefs.remove('transporter_user_id'); // Adjust key if needed
        // Clear cache
        await UserCache.removeData(_profileCacheKey);
        await UserCache.removeData(_profileCacheTimestampKey);
        _profileCache = null;
        _profileCacheTimestamp = null;

        if (mounted) {
          Navigator.pushAndRemoveUntil(
            context,
            MaterialPageRoute(builder: (context) => const TransporterLoginPage()), // Navigate to login
            (Route<dynamic> route) => false, // Remove all previous routes
          );
        }
      } catch (e) {
        print("Error during sign out: $e");
        _showErrorSnackBar("Could not sign out properly: $e");
         // Still attempt to navigate to login even if prefs/cache clearing fails
         if (mounted) {
           Navigator.pushAndRemoveUntil(
             context,
             MaterialPageRoute(builder: (context) => const TransporterLoginPage()),
             (Route<dynamic> route) => false,
           );
         }
      }
    }
  }


