  double _calculateTodaysEarnings() {
    DateTime now = DateTime.now();
    DateTime todayStart = DateTime(now.year, now.month, now.day);
    DateTime todayEnd = todayStart.add(Duration(days: 1));
    double total = 0;

    // Sum successful payments made today
    total += _payments
        .where((p) =>
            p.createdAt.isAfter(todayStart) &&
            p.createdAt.isBefore(todayEnd) &&
            p.disbursementTransactionStatus.toLowerCase() == 'successful')
        .fold(0.0, (sum, p) => sum + p.amount);

    // Removed the estimation logic based on completed orders without payments
    // Rely solely on the payments data for accuracy.
    return total;
  }

