  Future<void> _toggleOnlineStatus() async {
     if (_transporterProfile == null) {
       _showErrorSnackBar("Profile not loaded yet. Cannot change status.");
       return;
     }

     final bool targetStatus = !_isOnline; // Determine the target state

     _showLoadingSnackbar(targetStatus ? "Going Online..." : "Going Offline...");

     try {
       bool success = await TransporterApiService.updateTransporterActiveStatus(
           widget.transporterId, targetStatus);

       _dismissLoadingSnackbar(); // Dismiss loading *before* state update

       if (success && mounted) {
         // Update local state *after* successful API call
         setState(() {
           _isOnline = targetStatus;
           _transporterProfile = _transporterProfile?.copyWith(isActive: targetStatus);
           // Save updated profile to cache
           if (_transporterProfile != null) {
             _saveProfileCacheToPrefs(_transporterProfile!);
           }
         });
         _showSuccessSnackBar(targetStatus ? 'You are now Online!' : 'You are now Offline.');
       } else if (mounted) {
         // API call failed or component unmounted
         _showErrorSnackBar('Failed to update status. Please try again.');
         // Revert visual state if API failed (optional, but good UX)
         setState(() {
           _isOnline = !targetStatus; // Revert switch/button state
         });
       }
     } catch (e) {
       _dismissLoadingSnackbar();
       print("Failed to toggle online status: $e");
       if (mounted) {
         _showErrorSnackBar('Error updating status: ${e.toString()}');
          // Revert visual state on error
          setState(() {
            _isOnline = !targetStatus;
          });
       }
     }
   }

