  List<Order> _getRecentActivityOrders() {
    // Includes completed, cancelled, rejected
     List<Order> completedOrCancelled = _allOrders
         .where((o) => [
               Order.STATUS_COMPLETED,
               Order.STATUS_CANCELLED,
               Order.STATUS_RIDER_REJECTED,
               Order.STATUS_DELIVERED // Include delivered but not yet completed if desired
             ].contains(o.orderStatus))
         .toList();
     completedOrCancelled.sort((a, b) => b.orderDate.compareTo(a.orderDate)); // Most recent first
     return completedOrCancelled.take(3).toList(); // Limit to 3
   }

  List<Order> _getScheduledOrders() {
     // Orders assigned to the transporter but not yet started/picked up
     return _allOrders
         .where((o) => [Order.STATUS_ASSIGNED, Order.STATUS_RIDER_ACCEPTED].contains(o.orderStatus))
         .toList()
       ..sort((a, b) => a.orderDate.compareTo(b.orderDate)); // Oldest first (next up)
   }

