      appBar: AppBar(
        backgroundColor: primaryTeal, elevation: 2.0, iconTheme: const IconThemeData(color: textOnTeal),
        title: Text(_getAppBarTitle(), style: const TextStyle(color: textOnTeal, fontWeight: FontWeight.w600, fontSize: 18)),
