              child: ElevatedButton.icon(
                onPressed: _updateProducerStock,
                icon: const Icon(Icons.update, size: 20),
                label: const Text('UPDATE STOCK', style: TextStyle(letterSpacing: 0.5, fontWeight: FontWeight.bold)),
