          fit: BoxFit.cover, // Ensure asset covers the area
          errorBuilder: (context, error, stackTrace) {
            print("Error loading placeholder asset (Detail): $error");
            return Container(
                // Fallback solid color if asset fails
                color: kColorPrimaryLighter,
                child: Center(
