              ),
            ],
          ),
        ) ?? false;
        
        if (!shouldContinue) {
          return;
        }
        continueWithoutImage = true;
      }
      
      // Make location optional
      bool continueWithoutLocation = false;
      if (_locationCoordinates.isEmpty) {
        final shouldContinue = await showDialog<bool>(
          context: context,
