                child: const Text('Continue'),
              ),
            ],
          ),
        ) ?? false;
        
        if (!shouldContinue) {
          return;
        }
        continueWithoutLocation = true;
      }

      setState(() => _isLoading = true);

      Map<String, dynamic> signupData = {
