                                    borderRadius: BorderRadius.circular(8),
                                  ),
                                  backgroundColor: Colors.teal,
                                  elevation: 3,
                                  minimumSize: const Size(double.infinity, 60),
                                ),
                                child: _isLoading
                                    ? const CircularProgressIndicator(
                                        color: Colors.white)
                                    : const Text(
                                        'LOG IN',
                                        style: TextStyle(
                                            fontSize: 16, color: Colors.white),
                                      ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

