              accountEmail: _isLoading || _userEmail.isEmpty
                  ? null
                  : Text(
                      _userEmail,
                      style: GoogleFonts.poppins(
                        fontSize: 13,
                        color: kColorTextOnPrimary.withOpacity(0.8),
                      ),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
