                child: CircleAvatar(
                  radius: 35,
                  backgroundColor: kColorSurface.withOpacity(0.8),
                  backgroundImage: avatarImage,
                  onBackgroundImageError: (_, __) {
                    print("Error loading profile picture in drawer.");
                  },
                  child: _isLoading &&
                          _profileImageUrl == null &&
                          _profileImagePath == null
                      ? const SizedBox(
                          width: 20,
                          height: 20,
