                      : null,
                ),
              ),
              decoration: const BoxDecoration(
                color: kColorPrimaryDark,
              ),
              margin: EdgeInsets.zero,
            ),
            Expanded(
              child: ListView(
                padding: EdgeInsets.zero,
                children: _buildUserTypeSpecificTiles(),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

