        // Use pushReplacement if you don't want users going back to the cart easily
        context,
        MaterialPageRoute(
          builder: (context) => CheckoutScreen(
            items: cartItems, // Pass the current snapshot of items
            totalPrice: totalAmount, // Pass the rrent total
