  // <<< Fetch route using Mapbox Directions API >>>
  static Future<Map<String, dynamic>?> fetchRoute(mapbox.Point origin, mapbox.Point destination) async { // Use mapbox.Point
    if (mapboxAccessToken == null || mapboxAccessToken!.isEmpty) {
      print("Mapbox Access Token is missing for Directions API.");
      return null;
    }
    // IMPORTANT: mapbox_maps_flutter uses (longitude, latitude) order
    final String originCoords = "${origin.coordinates.lng},${origin.coordinates.lat}";
    final String destCoords = "${destination.coordinates.lng},${destination.coordinates.lat}";
    final profile = 'driving-traffic'; // Or 'driving', 'walking', 'cycling'
    final url =
        'https://api.mapbox.com/directions/v5/mapbox/$profile/$originCoords;$destCoords?alternatives=false&geometries=geojson&language=en&overview=full&steps=false&access_token=${mapboxAccessToken!}';

    print("Fetching route from Mapbox Directions: $url");

    try {
      final response = await http.get(Uri.parse(url));
      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        if (data['routes'] != null && data['routes'].isNotEmpty) {
          print("Route fetched successfully.");
          return data['routes'][0]; // Return the first route object (contains geometry, duration, distance)
        } else {
          print("No routes found in Mapbox Directions response: ${response.body}");
          return null;
        }
      } else {
        print("Error fetching route: ${response.statusCode} ${response.body}");
        return null;
      }
    } catch (e) {
      print("Exception fetching route: $e");
      return null;
    }
  }

