        _notifyNewOrders = prefs.getBool('notifyNewOrders') ?? true;
        _notifyStatusUpdates = prefs.getBool('notifyStatusUpdates') ?? true;
        _notifyEarnings = prefs.getBool('notifyEarnings') ?? true;
        _notifyPromotions = prefs.getBool('notifyPromotions') ?? false;
        // _useDarkMode = prefs.getBool('useDarkMode') ?? false; // Removed
        _soundAlerts = prefs.getBool('soundAlerts') ?? true;
        _autoNavigate = prefs.getBool('autoNavigate') ?? true;
      });
    } catch (e) {
      print("Error loading preferences: $e");
    }
  }

  Future<void> _initializeTransporterProfile() async {
    if (mounted) {
      setState(() {
         _isLoadingProfile = true;
         _profileFetchError = null;
       });
    }
    await _loadProfileCacheFromPrefs();
    if (_profileCache != null && mounted) {
      final now = DateTime.now();
      final bool cacheIsValid = _profileCacheTimestamp != null &&
          now.difference(_profileCacheTimestamp!) < DataRepository.profileCacheDuration;
      if (_transporterProfile == null || cacheIsValid) {
        if (cacheIsValid) {
          print("TransporterDashNew: Displaying valid cached profile.");
        } else {
          print("TransporterDashNew: Displaying expired cached profile while fetching.");
        }
        setStateIfMounted(() {
          _transporterProfile = _profileCache;
          _isOnline = _transporterProfile!.isActive;
          _updateProfileControllers(_transporterProfile!);
          _isLoadingProfile = !cacheIsValid; // Still loading if cache is expired
        });
      } else {
         print("TransporterDashNew: Valid profile already in state, proceeding to fetch.");
         setStateIfMounted(() => _isLoadingProfile = true);
      }
    } else if (mounted) {
      print("TransporterDashNew: No cached profile found, fetching...");
      setStateIfMounted(() => _isLoadingProfile = true);
    }
    await _fetchTransporterProfileAndUpdate();
  }

  Future<void> _fetchTransporterProfileAndUpdate() async {
    try {
      final profile = await TransporterApiService.fetchTransporterProfile(
          widget.transporterId);
      if (mounted &&
          (_transporterProfile == null ||
              profile.toJson().toString() !=
                  _transporterProfile!.toJson().toString())) {
        print("TransporterDashNew: Fetched fresh transporter profile data.");
        await _saveProfileCacheToPrefs(profile);
        setStateIfMounted(() {
          _transporterProfile = profile;
          _isOnline = profile.isActive;
          _updateProfileControllers(profile);
          _isLoadingProfile = false;
          _profileFetchError = null;
        });
      } else if (mounted) {
        print("TransporterDashNew: Fetched profile data is same as current state.");
        setStateIfMounted(() {
          _isLoadingProfile = false;
          _profileFetchError = null;
        });
      }
    } catch (error, stackTrace) {
      print("Error fetching fresh transporter profile (new): $error\n$stackTrace");
      if (mounted) {
        if (_transporterProfile == null) { // Only show fatal error if NO profile is available
          setStateIfMounted(() {
            _profileFetchError = 'Failed to load profile: $error';
            _isLoadingProfile = false;
            _isLoading = false; // Stop main loader if profile fails critically
            _errorMessage = _profileFetchError; // Show error in body
          });
        } else { // If we have a cached profile, just show a non-fatal error indicator
          print("TransporterDashNew: Failed to fetch fresh profile, showing cached version. Error: $error");
          setStateIfMounted(() {
            _isLoadingProfile = false; // Stop profile-specific loader
            _profileFetchError = "Couldn't refresh profile: $error"; // Store error for potential display
          });
          // Optionally show a snackbar about the refresh failure
          _showErrorSnackBar("Couldn't refresh profile data.");
        }
      }
    }
  }


  void setStateIfMounted(VoidCallback fn) {
    if (mounted) {
      setState(fn);
    }
  }

  Future<void> _loadInitialData() async {
    if (!mounted) return;
    setStateIfMounted(() {
      _isLoading = true;
      _errorMessage = null;
    });

    // Fetch profile concurrently (it handles its own loading state)
    _initializeTransporterProfile();

    try {
      // Fetch orders and payments
      final results = await Future.wait([
        TransporterApiService.fetchAllTransporterOrders(widget.transporterId),
        TransporterApiService.fetchTransporterPayments(widget.transporterId),
        TransporterApiService.fetchAvailableOrders(),
      ]);

      final allOrdersResult = results[0] as List<Order>;
      final paymentsResult = results[1] as List<Payment>;
      final availableOrdersResult = results[2] as List<Order>;

      // Combine and deduplicate orders (available might overlap with all)
      final allFetchedOrdersMap = <int, Order>{};
      // Prioritize orders from the 'all' endpoint if duplicates exist
      for (var order in allOrdersResult) {
        allFetchedOrdersMap[order.orderId] = order;
      }
      for (var order in availableOrdersResult) {
        allFetchedOrdersMap.putIfAbsent(order.orderId, () => order);
      }

      final combinedOrders = allFetchedOrdersMap.values.toList()
        ..sort((a, b) => b.orderDate.compareTo(a.orderDate)); // Sort by date descending

      setStateIfMounted(() {
        _allOrders = combinedOrders;
        _payments = paymentsResult;
        // Only set _isLoading false if profile isn't also loading *initially*
        // If profile is still loading but we have orders/payments, keep main loader?
        // Let's tie main loader to orders/payments primarily, profile has its own indicator.
        _isLoading = false;
        _errorMessage = null;
      });
    } catch (e, stackTrace) {
      print("Error loading initial data (orders/payments/available): $e\n$stackTrace");
      if (mounted) {
         // Don't overwrite fatal profile error if it occurred
        if (_errorMessage == null) {
          setStateIfMounted(() {
            _errorMessage = "Failed to load data: ${e.toString()}";
            _isLoading = false;
            _allOrders = []; // Clear potentially partial data
            _payments = [];
          });
        } else {
           // Profile error already showing, just stop loading other data
           setStateIfMounted(() {
             _isLoading = false;
           });
        }
      }
    }
  }


  void _updateProfileControllers(TransporterProfile profile) {
    // Only update if text is different to avoid cursor jumps
    if (_nameController.text != profile.name) _nameController.text = profile.name;
    if (_emailController.text != profile.email) _emailController.text = profile.email;
    if (_phoneController.text != (profile.phoneNumber ?? '')) _phoneController.text = profile.phoneNumber ?? '';
    if (_addressController.text != (profile.address ?? '')) _addressController.text = profile.address ?? '';
    if (_licensePlateController.text != (profile.licensePlate ?? '')) _licensePlateController.text = profile.licensePlate ?? '';

    // Use fallbacks if specific vehicle details aren't provided
    if (_vehicleMakeController.text != (profile.vehicleMake ?? '')) _vehicleMakeController.text = profile.vehicleMake ?? '';
    if (_vehicleModelController.text != (profile.vehicleModel ?? '')) _vehicleModelController.text = profile.vehicleModel ?? '';
    if (_vehicleYearController.text != (profile.vehicleYear ?? '')) _vehicleYearController.text = profile.vehicleYear ?? '';
    if (_vehicleColorController.text != (profile.vehicleColor ?? '')) _vehicleColorController.text = profile.vehicleColor ?? '';
  }

