                      style: ElevatedButton.styleFrom(backgroundColor: _primaryTeal, foregroundColor: _white),
                   )
                ]
             ],
           ),
         ),
       ),
     );
   }


  Widget _buildOrderDetailsCard() {
    // Placeholder phone numbers - replace with actual data if available
    String restaurantPhone = _currentOrder.orderType == 'meal' ? "(555) 123-CHEF" : "(555) 456-PROD";
    String customerPhone = "(555) 987-CUST"; // Needs real data source

